package com.restaurant.billing.api;
import org.springframework.web.bind.annotation.*; import java.util.Map; import java.util.UUID;
@RestController @RequestMapping("/api/v1") public class InvoiceAmendmentController { private final InvoiceAmendmentService amendments; private final ApprovedAmendmentApplicationService application; public InvoiceAmendmentController(InvoiceAmendmentService a,ApprovedAmendmentApplicationService s){amendments=a;application=s;} @PostMapping("/invoices/{invoiceId}/amendments") public Map<String,Object> request(@PathVariable UUID invoiceId,@RequestBody Map<String,String> body){return amendments.request(invoiceId,body.get("reasonCode"),body.get("notes"));} @PostMapping("/invoice-amendments/{id}/approve") public Map<String,Object> approve(@PathVariable UUID id,@RequestBody Map<String,String> body){try{return amendments.approve(id,UUID.fromString(body.get("approverId")),body.get("password"));}catch(IllegalArgumentException ex){throw com.restaurant.platform.api.ApiException.bad("APPROVER","A valid approver is required");}} @PostMapping("/invoice-amendments/{id}/apply") public Map<String,Object> apply(@PathVariable UUID id,@RequestBody Map<String,String> body){return application.apply(id,body.get("approvalToken"));}}
